const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a point for Beira, Mozambique
  const beiraPoint = ee.Geometry.Point(34.83, -19.84);
  // Define a point for Manga, Mozambique
  const mangaPoint = ee.Geometry.Point(34.90, -19.95);

  // Buffer points to create small areas for analysis
  const bufferSize = 5000; // 5 km buffer
  const beiraGeom = beiraPoint.buffer(bufferSize);
  const mangaGeom = mangaPoint.buffer(bufferSize);

  // Combine geometries for a single analysis region
  const analysisRegion = beiraGeom.union(mangaGeom);

  const date1 = '2019-03-09';
  const date2 = '2019-03-24';

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('NOAA/VIIRS/001/VNP46A1')
    .select(['DNB_At_Sensor_Radiance', 'Mandatory_Quality_Flag']);

  const getDayImage = (date) => {
    return collection.filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(analysisRegion);
  };

  const col1 = getDayImage(date1);
  const col2 = getDayImage(date2);

  const col1Size = await col1.size().getInfo();
  const col2Size = await col2.size().getInfo();

  if (col1Size === 0 || col2Size === 0) {
    console.log(`Images for ${date1}: ${col1Size}`);
    console.log(`Images for ${date2}: ${col2Size}`);
    console.log("C1: Empty Collection (No images found for one or both dates in the specified location).");
    return;
  }

  // Expecting a single image for each day
  const image1 = ee.Image(col1.first());
  const image2 = ee.Image(col2.first());

  // Function to mask invalid pixels (clouds, etc.)
  const applyQualityMask = (image) => {
    // Quality flag: 0 = Best quality, 1 = Good quality
    // We want to keep pixels with flag 0 or 1
    const qaBand = image.select('Mandatory_Quality_Flag');
    const goodQuality = qaBand.eq(0).or(qaBand.eq(1));
    return image.updateMask(goodQuality);
  };

  const maskedImage1 = applyQualityMask(image1);
  const maskedImage2 = applyQualityMask(image2);

  // 3. Processing & Calculation
  const band = 'DNB_At_Sensor_Radiance';
  const scale = 1000; // meters
  const maxPixels = 1e9;

  const reduceParams = {
    reducer: ee.Reducer.mean(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: maxPixels
  };

  const countParams = {
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: maxPixels
  };

  const result1 = await maskedImage1.select(band).reduceRegion(reduceParams).get(band).getInfo();
  const result2 = await maskedImage2.select(band).reduceRegion(reduceParams).get(band).getInfo();

  const count1 = await maskedImage1.select(band).reduceRegion(countParams).get(band).getInfo();
  const count2 = await maskedImage2.select(band).reduceRegion(countParams).get(band).getInfo();

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels for ${date1}: ${count1}`);
    console.log(`Valid pixels for ${date2}: ${count2}`);
    console.log("C2: No Valid Pixels (Images exist, but after quality masking, 0 valid pixels remain in the region).");
    return;
  }

  if (result1 === null || result2 === null || isNaN(result1) || isNaN(result2)) {
    console.log(`Radiance ${date1}: ${result1}`);
    console.log(`Radiance ${date2}: ${result2}`);
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  console.log(`Nighttime light intensity on ${date1} (Beira/Manga): ${result1.toFixed(4)} nW cm-2 sr-1 (Pixels: ${count1})`);
  console.log(`Nighttime light intensity on ${date2} (Beira/Manga): ${result2.toFixed(4)} nW cm-2 sr-1 (Pixels: ${count2})`);

  if (result2 < result1) {
    console.log("A: Yes"); // Nighttime light intensity was lower on March 24 compared to March 9.
  } else {
    console.log("B: No"); // Nighttime light intensity was not lower on March 24 compared to March 9.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
